package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_html_TriageGen1Test {



    @Test
    public void testHtml_WithAttributes() {
        Element element = new Element(Tag.valueOf("div"), "");
        element.attr("id", "test-id");
        element.attr("class", "test-class");
        // Note: Jsoup output order for attributes can vary, but usually follows insertion or alphabetical
        // For this test, we verify the content exists.
        String html = element.html();
        assertTrue(html.contains("id=\"test-id\""));
        assertTrue(html.contains("class=\"test-class\""));
        assertTrue(html.startsWith("<div"));
        assertTrue(html.endsWith("></div>"));
    }










}

