public class Element_html_TriageGen1Test {







    @Test
    public void testHtml_WithChildElements() {
        Element parent = new Element(Tag.valueOf("div"), "");
        Element child = new Element(Tag.valueOf("span"), "");
        child.appendText("Child Text");
        parent.appendChild(child);

        String expected = "<div><span>Child Text</span></div>";
        assertEquals(expected, parent.html());
    }






}

